1	package clinical
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sync"
12		"time"
13	)
14	
15	// dataName 是存放全部业务状态的快照文件名。
16	const dataName = "clinical-data.json"
17	
18	// dataVersion 是快照格式的版本标记，便于将来迁移。
19	const dataVersion = 1
20	
21	// snapshot 是写入磁盘的完整状态。所有业务对象集中在一个文件中，
22	// 采用“临时文件 + 原子改名”整体落盘：成功操作与其审计事件一同保留，
23	// 失败的操作在 mutate 中就已丢弃，不会写出半截状态。
24	type snapshot struct {
25		FormatVersion  int                       `json:"format_version"`
26		Patients       map[string]*Patient       `json:"patients"`
27		Encounters     map[string]*Encounter     `json:"encounters"`
28		Records        map[string]*Record        `json:"records"`
29		Versions       map[string]*Version       `json:"versions"`
30		Authorizations map[string]*Authorization `json:"authorizations"`
31		Exchanges      map[string]*Exchange      `json:"exchanges"`
32		AuditEvents    []*AuditEvent             `json:"audit_events"`
33	}
34	
35	// Clock 决定“发生时间”的来源。生产使用实时时钟；测试可注入固定/可控时钟
36	// 以验证开始、到期、撤回等时间边界。
37	type Clock func() time.Time
38	
39	// Store 是本地临床档案的句柄。数据存放位置由调用方在 Open 时指定。
40	// 同一目录同一时刻只允许一个 Store 打开（通过锁文件互斥）。
41	type Store struct {
42		dir   string
43		clock Clock
44		mu    sync.Mutex
45		lock  *os.File
46		data  *snapshot
47	}
48	
49	// Option 配置 Open 的行为。
50	type Option func(*Store)
51	
52	// WithClock 注入自定义时钟。
53	func WithClock(c Clock) Option {
54		return func(s *Store) { s.clock = c }
55	}
56	
57	// Open 在指定目录打开（必要时创建）本地存储。
58	// 调用方指定数据存放位置；关闭后从同一位置重新打开可看到全部历史，
59	// 到期与否始终按“本次读取时间”重新计算。
60	//
61	// 相对路径只在本次 Open 调用时按当前工作目录解释，并立即固定为绝对路径：
62	// 句柄成功打开后，即使调用进程随后切换工作目录，该句柄的读取与落盘仍始终
63	// 指向打开时确定的目录，既不会把数据写到新工作位置下的同名目录，也不会因
64	// 新位置缺少该目录而让原本可成功的保存失败。切换工作目录后另行调用 Open
65	// 时，相对路径仍按新调用时刻的工作位置重新解释。
66	func Open(dir string, opts ...Option) (*Store, error) {
67		if dir == "" {
68			return nil, fmt.Errorf("%w: empty data directory", ErrInvalidArgument)
69		}
70		// 在创建目录之前就把路径固定为绝对路径。此时路径尚不存在也没关系：
71		// Abs 只做词法解析，不访问文件系统；后续 MkdirAll 与所有读写都使用
72		// 这个固定值，与进程工作目录再无关系。
73		absDir, err := filepath.Abs(dir)
74		if err != nil {
75			return nil, err
76		}
77		dir = absDir
78		if err := os.MkdirAll(dir, 0o755); err != nil {
79			return nil, err
80		}
81	
82		lockPath := filepath.Join(dir, ".clinical.lock")
83		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
84		if err != nil {
85			return nil, err
86		}
87		if err := tryLockFile(lockFile); err != nil {
88			lockFile.Close()
89			return nil, err
90		}
91	
92		s := &Store{dir: dir, clock: time.Now, lock: lockFile}
93		for _, opt := range opts {
94			opt(s)
95		}
96		if s.clock == nil {
97			s.clock = time.Now
98		}
99	
100		if err := s.loadLocked(); err != nil {
101			unlockFile(lockFile)
102			lockFile.Close()
103			return nil, err
104		}
105		return s, nil
106	}
107	
108	func (s *Store) loadLocked() error {
109		path := filepath.Join(s.dir, dataName)
110		raw, err := os.ReadFile(path)
111		if os.IsNotExist(err) {
112			s.data = newSnapshot()
113			return nil
114		}
115		if err != nil {
116			return err
117		}
118		var snap snapshot
119		if err := json.Unmarshal(raw, &snap); err != nil {
120			return err
121		}
122		if snap.FormatVersion != dataVersion {
123			return fmt.Errorf("clinical: unsupported data format version %d", snap.FormatVersion)
124		}
125		ensureMaps(&snap)
126		s.data = &snap
127		return nil
128	}
129	
130	func newSnapshot() *snapshot {
131		snap := &snapshot{FormatVersion: dataVersion}
132		ensureMaps(snap)
133		return snap
134	}
135	
136	func ensureMaps(snap *snapshot) {
137		if snap.Patients == nil {
138			snap.Patients = map[string]*Patient{}
139		}
140		if snap.Encounters == nil {
141			snap.Encounters = map[string]*Encounter{}
142		}
143		if snap.Records == nil {
144			snap.Records = map[string]*Record{}
145		}
146		if snap.Versions == nil {
147			snap.Versions = map[string]*Version{}
148		}
149		if snap.Authorizations == nil {
150			snap.Authorizations = map[string]*Authorization{}
151		}
152		if snap.Exchanges == nil {
153			snap.Exchanges = map[string]*Exchange{}
154		}
155	}
156	
157	// Close 刷新并释放数据目录。Close 后任何业务方法返回 ErrClosed。
158	func (s *Store) Close() error {
159		s.mu.Lock()
160		defer s.mu.Unlock()
161		if s.lock == nil {
162			return ErrClosed
163		}
164		unlockFile(s.lock)
165		err := s.lock.Close()
166		if rmErr := removeLockFile(filepath.Join(s.dir, ".clinical.lock")); rmErr != nil && !os.IsNotExist(rmErr) && err == nil {
167			err = rmErr
168		}
169		s.lock = nil
170		s.data = nil
171		return err
172	}
173	
174	func (s *Store) now() time.Time { return s.clock().UTC() }
175	
176	// errUnchanged 由 mutate 的 fn 返回，表示本次操作只读取了既有结果、
177	// 没有产生任何状态变更（例如幂等重试命中已保存的结果）：直接成功返回，
178	// 不触发落盘。这样重试即使赶上本地保存条件不可用，也能返回原结果。
179	var errUnchanged = errors.New("clinical: no state change")
180	
181	// mutate 在状态的深拷贝上执行业务变更。fn 返回错误时，拷贝连同其中的
182	// 半成品一并丢弃，磁盘与既有业务状态保持原样；fn 返回 nil 时整体原子落盘。
183	// 这样“引用不存在的对象/跨患者混用”等失败都不会留下半条记录。
184	// fn 返回 errUnchanged 时视为成功但不落盘：状态没有任何变化，无需重写数据。
185	func (s *Store) mutate(fn func(*snapshot) error) error {
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		if s.data == nil {
189			return ErrClosed
190		}
191	
192		clone := cloneSnapshot(s.data)
193		if err := fn(clone); err != nil {
194			if errors.Is(err, errUnchanged) {
195				return nil
196			}
197			return err
198		}
199		if err := s.persist(clone); err != nil {
200			return err
201		}
202		s.data = clone
203		return nil
204	}
205	
206	// view 在只读快照上执行查询。
207	func (s *Store) view(fn func(*snapshot) error) error {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if s.data == nil {
211			return ErrClosed
212		}
213		return fn(s.data)
214	}
215	
216	func (s *Store) persist(snap *snapshot) error {
217		raw, err := json.MarshalIndent(snap, "", "  ")
218		if err != nil {
219			return err
220		}
221		final := filepath.Join(s.dir, dataName)
222		tmp := filepath.Join(s.dir, dataName+".tmp")
223		if err := os.WriteFile(tmp, raw, 0o600); err != nil {
224			return err
225		}
226		if err := os.Rename(tmp, final); err != nil {
227			_ = os.Remove(tmp)
228			return err
229		}
230		return nil
231	}
232	
233	func cloneSnapshot(in *snapshot) *snapshot {
234		out := &snapshot{
235			FormatVersion:  in.FormatVersion,
236			Patients:       make(map[string]*Patient, len(in.Patients)),
237			Encounters:     make(map[string]*Encounter, len(in.Encounters)),
238			Records:        make(map[string]*Record, len(in.Records)),
239			Versions:       make(map[string]*Version, len(in.Versions)),
240			Authorizations: make(map[string]*Authorization, len(in.Authorizations)),
241			Exchanges:      make(map[string]*Exchange, len(in.Exchanges)),
242			AuditEvents:    make([]*AuditEvent, 0, len(in.AuditEvents)),
243		}
244		for k, v := range in.Patients {
245			p := *v
246			out.Patients[k] = &p
247		}
248		for k, v := range in.Encounters {
249			e := *v
250			out.Encounters[k] = &e
251		}
252		for k, v := range in.Records {
253			r := *v
254			r.Versions = append([]ID(nil), v.Versions...)
255			out.Records[k] = &r
256		}
257		for k, v := range in.Versions {
258			vv := *v
259			out.Versions[k] = &vv
260		}
261		for k, v := range in.Authorizations {
262			a := *v
263			a.Scopes = append([]Scope(nil), v.Scopes...)
264			a.Selections = append([]RecordSelection(nil), v.Selections...)
265			if v.RevokedAt != nil {
266				t := *v.RevokedAt
267				a.RevokedAt = &t
268			}
269			out.Authorizations[k] = &a
270		}
271		for k, x := range in.Exchanges {
272			y := *x
273			y.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
274			if x.Receipt != nil {
275				r := *x.Receipt
276				y.Receipt = &r
277			}
278			out.Exchanges[k] = &y
279		}
280		for _, ev := range in.AuditEvents {
281			e := *ev
282			out.AuditEvents = append(out.AuditEvents, &e)
283		}
284		return out
285	}
286	
287	func newID(prefix string) string {
288		var b [12]byte
289		if _, err := rand.Read(b[:]); err != nil {
290			// crypto/rand 失败在正常运行环境中不应发生；无法安全生成标识时直接中断。
291			panic(fmt.Errorf("clinical: cannot generate id: %w", err))
292		}
293		return prefix + "_" + hex.EncodeToString(b[:])
294	}
295	
296	func (s *Store) addAudit(snap *snapshot, patientID ID, actor Actor, action, objectType, objectID ID, at time.Time) {
297		snap.AuditEvents = append(snap.AuditEvents, &AuditEvent{
298			ID:         newID("aud"),
299			PatientID:  patientID,
300			ActorID:    actor.ID,
301			Action:     action,
302			ObjectType: objectType,
303			ObjectID:   objectID,
304			OccurredAt: at,
305		})
